from true_rl_agent.candidates.components import RewardInputs, RewardTerm, TrainingComponents

def upright_velocity_margin(inp: RewardInputs):
    tilt = inp.roll * inp.roll + inp.pitch * inp.pitch
    return inp.base_height - 0.25 * tilt

def build_training_components() -> TrainingComponents:
    return TrainingComponents(
        name='upright_velocity_margin_candidate',
        reward_terms=[RewardTerm(name='upright_velocity_margin', weight=1.0, fn=upright_velocity_margin)],
        rationale='Reward upright posture using public RewardInputs.',
    )

